styles.tutorial:
section[data-skill-hub] .-w {
  display: grid;
  grid-template-columns: repeat(14, 1fr);
  grid-template-rows: repeat(2, 1fr);
  align-items: start;
  column-gap: var(--g-gap);
  position: relative;
  min-height: 1024px;
}
section[data-skill-hub] .-w p {
  grid-column-start: 3;
  grid-column-end: 13;
  grid-row-start: 1;
  justify-self: center;
  align-self: start;
  text-align: center;
  z-index: 40;
  margin-top: calc(var(--h1) * 2);
  padding-left: 10%;
  padding-right: 10%;

}
@media (min-width: 1024px) {
  section[data-skill-hub] .-w p {
    grid-column-start: 6;
    grid-column-end: 10;
  }
}
section[data-skill-hub] .-w .image-1 {
  grid-column-start: 1;
  grid-column-end: 15;
  grid-row-start: 1;
  align-self: center;
  height: calc(var(--vh, 1vh) * 40);
  position: sticky;
  top: calc(var(--vh, 1vh) * 30);
  margin-bottom: calc(var(--vh, 1vh) * 30);
  scale: calc(0.5 + var(--progress) * 0.5);
  clip-path: rect(
    calc(20% - var(--progress) * 20%) calc(90% + var(--progress) * 10%) calc(80% + var(--progress) * 20%) calc(10% - var(--progress) * 10%)
      round calc(var(--h3) - var(--progress) * var(--h3))
  );
  transform: translateZ(0);

}
@media (min-width: 1024px) {
  section[data-skill-hub] .-w .image-1 {
    grid-column-start: 3;
    grid-column-end: 13;
    top: calc(var(--vh, 1vh) * 15);
    margin-bottom: calc(var(--vh, 1vh) * 15);
    height: calc(var(--vh, 1vh) * 70);
    clip-path: rect(
      calc(20% - var(--progress) * 20%) calc(70% + var(--progress) * 30%) calc(80% + var(--progress) * 20%)
        calc(30% - var(--progress) * 30%) round calc(var(--h3) - var(--progress) * var(--h3))
    );
  }
}
section[data-skill-hub] .-w .image-1 img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
section[data-skill-hub] .-w span.line {
  grid-column-start: 1;
  grid-column-end: 15;
  grid-row-start: 1;
  align-self: center;
  position: relative;
  display: block;
  height: 1px;
  background-color: var(--c-grey-dark);
  margin-top: calc(var(--vh, 1vh) * 30);
  opacity: 0.4;

}
@media (min-width: 1024px) {
  section[data-skill-hub] .-w span.line {
    margin-top: calc(var(--vh, 1vh) * 15);
  }
}
section[data-skill-hub] .-w .title {
  grid-column-start: 1;
  grid-column-end: 15;
  grid-row-start: 1;

  align-self: end;
  text-align: center;
  position: relative;
}
